// Public holidays (days off) on a trip's days, national and regional, for any country (User, 2026-10-31: a "Holiday"
// tag on the day cards, how many on the days list's title, the name and kind on the day's page, with an "i" about
// the busy week it falls in).
// Data: public/holidays/<CC>.json, generated by `npm run holidays:update` from the date-holidays package (ISC, data
// CC-BY-3.0), fetched from the app's own site once per country and kept on the device (localStorage), so offline after.
// A regional holiday counts on a day only when its region is named in the addresses of that city's places
// ("Kazan, Republic of Tatarstan, Russia"; US / Brazil addresses carry the state code: "CA 94103", "- SP,").

import { useEffect, useMemo, useState } from 'react'
import type { Day, Place, Stay, Trip } from '../db/model'
import { staysOn } from '../db/stays'
import { loadJson, saveJson } from '../settings'

interface HolidayFile {
  from: number
  to: number
  /** Region code → its English name, and the local one when different. */
  regions: Record<string, string[]>
  /** [date, name] */
  national: [string, string][]
  /** [date, name, region codes] */
  regional: [string, string, string[]][]
}

export interface DayHoliday {
  date: string
  name: string
  country: string
  /** Region names where it is a day off; none = national. */
  regions?: string[]
  /** About the busy holiday week it falls in (Golden Week…), shown behind an "i". */
  note?: string
}

/** Busy holiday weeks worth a word, beyond the days off themselves ("MM-DD" ranges, inclusive). */
const PERIODS: { country: string; from: string; to: string; text: string }[] = [
  { country: 'JP', from: '04-29', to: '05-05', text: 'Golden Week, 29 Apr – 5 May: Japan’s busiest holiday week. Crowded trains and sights, higher prices: book early.' },
  { country: 'JP', from: '08-13', to: '08-16', text: 'Obon, 13–16 Aug: many people travel home. Busy trains and roads.' },
  { country: 'JP', from: '12-29', to: '01-03', text: 'New Year holidays, 29 Dec – 3 Jan: many shops, museums and restaurants close.' },
]

const STORAGE_PREFIX = 'tabi.holidays.'
const known = new Map<string, HolidayFile>()
const pending = new Map<string, Promise<void>>()

function storedFile(country: string): HolidayFile | undefined {
  let file = known.get(country)
  if (!file) {
    file = loadJson<HolidayFile>(STORAGE_PREFIX + country) ?? undefined
    if (file) known.set(country, file)
  }
  return file
}

/** Fetched once per app session (the files are refreshed now and then); a country without a file just has none. */
function fetchOnce(country: string): Promise<void> {
  let request = pending.get(country)
  if (!request) {
    request = fetch(`${import.meta.env.BASE_URL}holidays/${country}.json`)
      .then((response) => (response.ok ? (response.json() as Promise<HolidayFile>) : null))
      .then((file) => {
        if (!file) return
        known.set(country, file)
        saveJson(STORAGE_PREFIX + country, file)
      })
      .catch(() => {})
    pending.set(country, request)
  }
  return request
}

/** Lower case, without accents: "Republic of Tatarstan" matches "republic of tatarstan". */
const plain = (text: string) => text.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
const escape = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

function regionNamed(code: string, names: string[], text: string, raw: string): boolean {
  if (names.some((name) => name.length >= 4 && text.includes(plain(name)))) return true
  // A state code after a comma or dash, as in US and Brazilian addresses.
  return new RegExp(`[,-]\\s*${escape(code)}(?=[\\s,]|$)`).test(raw)
}

const countryName = (code: string) => {
  try {
    return new Intl.DisplayNames(['en'], { type: 'region' }).of(code) ?? code
  } catch {
    return code
  }
}

export interface TripHolidays {
  /** Day id → its holidays. */
  byDay: Map<string, DayHoliday[]>
}

function computeHolidays(trip: Trip, days: Day[], places: Place[], stays: Stay[], ready: string[]): TripHolidays {
  const countries = trip.countries ?? []
  const byDay = new Map<string, DayHoliday[]>()
  if (countries.length === 0) return { byDay }

  // The addresses of each city's places, for the days of that city (a free day has none of its own).
  const addressesOf = new Map<string, string[]>()
  const dayCities = (day: Day) => staysOn(stays, day.date).map((s) => s.city)
  for (const day of days) {
    const own = places.filter((p) => p.dayId === day.id).flatMap((p) => (p.address ? [p.address] : []))
    for (const city of dayCities(day)) addressesOf.set(city, [...(addressesOf.get(city) ?? []), ...own])
  }

  for (const day of days) {
    const cities = dayCities(day)
    const raw = [...places.filter((p) => p.dayId === day.id).flatMap((p) => (p.address ? [p.address] : [])), ...cities.flatMap((c) => [c, ...(addressesOf.get(c) ?? [])])].join(' | ')
    const text = plain(raw)
    // With one country it's that one; else the one named in the addresses ("…, Japan").
    const inCountries = countries.length === 1 ? countries : countries.filter((c) => text.includes(plain(countryName(c))))
    const found: DayHoliday[] = []
    for (const country of inCountries) {
      const file = ready.includes(country) ? storedFile(country) : undefined
      if (!file) continue
      for (const [date, name] of file.national) if (date === day.date) found.push({ date, name, country })
      for (const [date, name, codes] of file.regional) {
        if (date !== day.date) continue
        const matched = codes.filter((code) => regionNamed(code, file.regions[code] ?? [], text, raw))
        if (matched.length) found.push({ date, name, country, regions: matched.map((code) => file.regions[code]?.[0] ?? code) })
      }
    }
    const md = day.date.slice(5)
    for (const h of found) {
      const period = PERIODS.find((p) => p.country === h.country && (p.from <= p.to ? md >= p.from && md <= p.to : md >= p.from || md <= p.to))
      if (period) h.note = period.text
    }
    if (found.length) byDay.set(day.id, found)
  }
  return { byDay }
}

/** The trip's holidays; the country files are fetched once while online. */
export function useTripHolidays(
  trip: Trip | null | undefined,
  days: Day[] | undefined,
  places: Place[] | undefined,
  stays: Stay[] | undefined,
  online: boolean,
): TripHolidays | undefined {
  const countries = (trip?.countries ?? []).join(',')
  // Bumped when the files arrive, to read them.
  const [, setLoaded] = useState(0)

  useEffect(() => {
    if (!online || !countries) return
    let alive = true
    void Promise.all(countries.split(',').map(fetchOnce)).then(() => {
      if (alive) setLoaded((n) => n + 1)
    })
    return () => {
      alive = false
    }
  }, [countries, online])

  // Which files are here: computed again when one arrives.
  const ready = countries
    .split(',')
    .filter((c) => c && storedFile(c))
    .join(',')
  return useMemo(
    () => (trip && days && places && stays ? computeHolidays(trip, days, places, stays, ready.split(',')) : undefined),
    [trip, days, places, stays, ready],
  )
}

/** "National holiday" / "Regional holiday · Republic of Tatarstan", with the country when the trip has several. */
export function holidayKind(holiday: DayHoliday, trip: Trip): string {
  const kind = holiday.regions ? `Regional holiday · ${holiday.regions.join(', ')}` : 'National holiday'
  return (trip.countries ?? []).length > 1 ? `${kind} · ${countryName(holiday.country)}` : kind
}
